import { test, expect } from '@playwright/test';

test.describe('Optimistic UI Updates for Liking a Post', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/posts');
  });

  test('should optimistically update like count and heart icon before API response', async ({ page }) => {
    // Setup: intercept the initial GET request
    await page.route('**/api/posts/*', (route) => {
      route.continue();
    });

    // Setup: intercept the POST request and delay response
    await page.route('**/api/posts/*/like', (route) => {
      setTimeout(() => {
        route.abort('timedout');
      }, 1000);
    });

    // Get the first post using getByRole
    const postContainer = page.getByRole('region', { name: /post/i });
    await expect(postContainer).toBeVisible();

    // Get the like button using getByRole
    const likeButton = page.getByRole('button', { name: /like/i });
    await expect(likeButton).toBeVisible();

    // Get the like count using getByText
    const likeCount = page.getByText(/10/);
    await expect(likeCount).toBeVisible();

    // Get the heart icon using getByRole
    const heartIcon = page.getByRole('img', { name: /heart/i });
    await expect(heartIcon).not.toHaveClass(/liked/);

    // Click the like button
    await likeButton.click();

    // Verify optimistic update immediately
    await expect(likeCount).toHaveText(/11/);
    await expect(heartIcon).toHaveClass(/liked/);

    // Verify loading state appears
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Wait for API response
    await page.waitForTimeout(1100);

    // Verify optimistic update persists after API response
    await expect(likeCount).toHaveText(/11/);
    await expect(heartIcon).toHaveClass(/liked/);

    // Verify loading state disappears
    await expect(loadingIndicator).not.toBeVisible();
  });

  test('should revert optimistic update if API request fails', async ({ page }) => {
    // Setup: intercept the initial GET request
    await page.route('**/api/posts/*', (route) => {
      route.continue();
    });

    // Setup: intercept the POST request and return error
    await page.route('**/api/posts/*/like', (route) => {
      route.abort('failed');
    });

    // Get the first post using getByRole
    const postContainer = page.getByRole('region', { name: /post/i });
    await expect(postContainer).toBeVisible();

    // Get the like button using getByRole
    const likeButton = page.getByRole('button', { name: /like/i });
    await expect(likeButton).toBeVisible();

    // Get the like count using getByText
    const likeCount = page.getByText(/10/);
    await expect(likeCount).toBeVisible();

    // Get the heart icon using getByRole
    const heartIcon = page.getByRole('img', { name: /heart/i });
    await expect(heartIcon).not.toHaveClass(/liked/);

    // Click the like button
    await likeButton.click();

    // Verify optimistic update immediately
    await expect(likeCount).toHaveText(/11/);
    await expect(heartIcon).toHaveClass(/liked/);

    // Verify loading state appears
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Wait for API response
    await page.waitForTimeout(1100);

    // Verify optimistic update is reverted
    await expect(likeCount).toHaveText(/10/);
    await expect(heartIcon).not.toHaveClass(/liked/);

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to like post/i);
    await expect(errorMessage).toBeVisible();

    // Verify loading state disappears
    await expect(loadingIndicator).not.toBeVisible();
  });
});
